setflag FLAG_HIDE_LITTLEROOT_TOWN_BRENDANS_HOUSE_2F_POKE_BALL
setvar VAR_LITTLEROOT_HOUSES_STATE_BRENDAN 1
setdynamicwarp LittlerootTown 3 10
releaseall
end
= InsideOfTruck_EventScript_MovingBox
msgbox	The box is printed with a POKéMON logo.It's a POKéMON brand moving and delivery service.
end
